(function () {
  'use strict';
  const U = window.QAUI;
  const e = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
  const icon = name => U.render(U.n('Icon', {name, size: 18}));
  function define(name, props, render) {
    U.registry[name] = {name, label: name, group: '재설계 시안', description: '실행 상세 구조 비교용 공통 컴포넌트', props, render};
  }
  define('DesignShell', ['variant', 'description'], (p, children) => {
    const nav = [['activity','실행 현황'], ['list','시나리오'], ['workflow','요구사항 추적'], ['monitor','환경 및 기기'], ['chart','리포트'], ['folder','증거 보관함']];
    return '<div class="rd-app"><a class="rd-skip" href="#qa-main">본문으로 이동</a><aside class="rd-sidebar"><div class="rd-brand">' + U.render(U.n('BrandMark', {size:'md', label:''})) + '<strong>QAutra</strong></div><div class="rd-project"><strong>스토어 QA</strong><span>로컬 작업 공간 · 디자인 예시</span></div><nav aria-label="주 탐색">' + nav.map((v,i) => '<div class="rd-nav-item'+(i===0?' rd-current':'')+'">'+icon(v[0])+'<span>'+e(v[1])+'</span>'+(i===0?'<span class="rd-nav-note">현재</span>':'')+'</div>').join('') + '</nav><div class="rd-sidebar-foot">'+icon('settings')+'<span>설정</span><p>화면 배치 비교 단계<br>실제 엔진 연결 없음</p></div></aside><div class="rd-workspace"><header class="rd-topbar"><span>스토어 QA <span class="rd-slash">/</span> 실행 상세</span><strong>디자인 예시 · 실제 테스트 없음</strong></header><div class="rd-designbar"><div><strong>실행 상세 · 구조 비교</strong><p>'+e(p.description)+'</p></div><div class="rd-variants" aria-label="화면 구성 시안">'+['A','B','C'].map(v=>'<button type="button" data-action="variant" data-variant="'+v+'" aria-pressed="'+(p.variant===v)+'">시안 '+v+'</button>').join('')+'</div></div><main id="qa-main" class="rd-content" tabindex="-1">'+children+'</main><div id="qa-modal-root"></div><div id="qa-toast-root" class="qa-toast-root" aria-live="polite"></div></div></div>';
  });
  define('ExecutionLayout', ['variant', 'preview', 'steps', 'checks'], p => '<div class="rd-execution rd-layout-'+e(p.variant)+'"><div class="rd-region rd-region-preview">'+U.render(p.preview)+'</div><div class="rd-region rd-region-steps">'+U.render(p.steps)+'</div><div class="rd-region rd-region-checks">'+U.render(p.checks)+'</div></div>');
  define('ExecutionHeading', ['status', 'label', 'done', 'description'], p => '<section class="rd-heading"><div><div class="rd-heading-meta">SC-006 · 발행 r3 · 실행 시도 01</div><h1>쿠폰 적용 금액 검증</h1><p>'+e(p.description)+'</p></div><div class="rd-heading-status">'+U.render(U.n('Badge',{status:p.status,label:p.label}))+'<span>'+e(p.done)+' / 4 필수 검증</span></div></section>');
  define('SpacePreview', ['status', 'timestamp'], p => '<section class="rd-space" aria-labelledby="space-title"><div class="rd-section-head"><div><h2 id="space-title">Chrome · 데스크톱</h2><p>Linux worker · 독립 브라우저 세션</p></div>'+U.render(U.n('Badge',{status:p.status==='running'?'running':'stopped',label:p.status==='running'?'관측 예시':'저장 화면 예시'}))+'</div><div class="rd-browser"><div class="rd-browser-bar">'+icon('lock')+'<span>store.test / checkout</span><span class="rd-sample">샘플 화면</span></div><div class="rd-browser-content">'+U.render(U.n('Capture',{failed:true}))+'</div></div><div class="rd-space-meta"><span>'+icon('clock')+'관측 '+e(p.timestamp)+'</span><span>'+icon('monitor')+'페이지 영역 · 1440 × 900 예시</span></div><div class="rd-input-boundary">'+icon('info')+'<p><strong>입력은 테스트 환경 내부로만</strong><span>호스트 마우스·키보드·포커스를 사용하지 않는 설계예요. 실제 비간섭 검증 결과는 아니에요.</span></p></div></section>');
  define('StepList', ['items'], p => '<section class="rd-steps" aria-labelledby="steps-title"><div class="rd-section-head"><div><h2 id="steps-title">실행 단계</h2><p>하나의 연속 흐름 · 새 세션으로 쪼개지 않음</p></div></div><ol class="rd-step-list">'+p.items.map((v,i)=>'<li class="rd-step rd-step-'+e(v.status)+'"><span class="rd-step-number">'+(i+1)+'</span><div><strong>'+e(v.title)+'</strong><p>'+e(v.detail)+'</p>'+U.render(U.n('Badge',{status:v.status,label:v.label}))+'</div></li>').join('')+'</ol></section>');
  define('CheckPanel', ['status', 'evidence'], p => {
    const unknown = p.status === 'unknown';
    const values = unknown
      ? '<div class="rd-expect"><span>기대값<strong>25,000원</strong></span><span>최신 관측<strong>미확인</strong></span></div>'
      : '<div class="rd-expect"><span>기대값<strong>25,000원</strong></span><span>관측값<strong>28,000원</strong></span></div>';
    const note = unknown
      ? '주문 요약 열기의 변경 결과를 확인하지 못했어요. 저장 화면을 최신 결과로 판단하지 않아요.'
      : '선택한 주문의 최종 결제 금액이 쿠폰 할인 3,000원을 반영해야 해요.';
    return '<section class="rd-checks" aria-labelledby="checks-title"><div class="rd-section-head"><div><h2 id="checks-title">검증과 증거</h2><p>실행 종료와 업무 통과는 달라요</p></div></div><div class="rd-check-detail"><span class="rd-label">현재 검증 · 주문 요약의 최종 금액</span>'+values+'<p>'+e(note)+'</p></div><dl class="rd-result-facts"><div><dt>업무 판정</dt><dd>'+e(p.status==='failed'?'불일치 확인':unknown?'판단 근거 부족':'검증 중')+'</dd></div><div><dt>영상</dt><dd>'+e(p.evidence)+'</dd></div><div><dt>정리</dt><dd>'+e(p.status==='failed'?'완료 예시':unknown?'확인 필요 · 재사용 금지':'실행 종료 후 확인')+'</dd></div><div><dt>실행 정의</dt><dd>r3 · 실행 중 변경 없음</dd></div></dl><div class="rd-check-note">'+icon('info')+'<span>이 숫자와 화면은 디자인 샘플이에요. 실제 제품의 테스트 결과가 아니에요.</span></div></section>';
  });
  define('ExecutionToolbar', ['state'], p => '<section class="rd-toolbar" aria-label="실행 동작"><div class="rd-state-picker"><label for="design-state">디자인 상태</label><select id="design-state"><option value="running"'+(p.state==='running'?' selected':'')+'>실행 중</option><option value="failed"'+(p.state==='failed'?' selected':'')+'>제품 실패 · 증거 저장 완료</option><option value="unknown"'+(p.state==='unknown'?' selected':'')+'>결과 미확인 · 복구 필요</option></select></div><div class="rd-toolbar-actions">'+U.render(U.n('Button',{label:p.state==='running'?'중지 후 정리':p.state==='failed'?'실패 증거 보기':'복구 상태 확인',icon:p.state==='running'?'stop':p.state==='failed'?'play':'refresh',action:'primary',variant:'primary'}))+U.render(U.n('Button',{label:'실행 조건',icon:'list',action:'conditions'}))+'</div></section>');
})();
